/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isArrayLikeObject = require( '@stdlib/assert/is-array-like-object' );
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var copy = require( '@stdlib/array/base/copy' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:visualization:set:projections' );


// MAIN //

/**
* Sets cartographic projections.
*
* @private
* @param {ArrayLikeObject<Projection>} value - input value
* @throws {TypeError} must be an array of projections
* @returns {void}
*/
function set( value ) {
	if ( !isArrayLikeObject( value ) ) { // FIXME: validate array of projections or an empty array
		throw new TypeError( format( 'invalid assignment. `%s` must be an array of projections. Value: `%s`.', 'projections', value ) );
	}
	value = copy( value );
	if ( !hasEqualValues( value, this._projections ) ) {
		this._removeChangeListeners( this._projections );
		debug( 'Current value: %s. New value: %s.', JSON.stringify( this._projections ), JSON.stringify( value ) );
		this._projections = value;
		this.emit( 'change' );
		this._addChangeListeners( this._projections );
	}
}


// EXPORTS //

module.exports = set;
